<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class membelltype extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY."membellmodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId		    									    = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if($VarId<>'' && base64_decode(urldecode($VarId))) {            $VarUserId                                          = base64_decode(urldecode($VarId));            $ArrResults     									= $this->membellmodel->fnGetEmbellTypeInfo('','',$VarUserId);            $ArrData['ArrBasicInfo']	    				    = $ArrResults[0];            $ArrData['VarId']					                = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY.'addeditembelltype',$ArrData);    }    public function updateEmbellInfo() {        $ArrResult                                              = array();        $VarUserLoggedInfo                                      = fnGetUserLoggedInfo(1);        $VarEmbellName				    						= xssclean($this->input->post('en'));        $VarMedium  				    						= xssclean($this->input->post('m'));        $VarStatus												= xssclean($this->input->post('s'));        $VarId       											= xssclean($this->input->post('id'));        if($VarEmbellName<>'') {            $ArrUpdateData                                      = array('id'=>$VarId,'embellname'=>$VarEmbellName,'medium'=>$VarMedium,'companyid'=>$VarUserLoggedInfo['companyid'],'status'=>$VarStatus,'updatedby'=>$VarUserLoggedInfo['id'],'dateupdated'=>date('Y-m-d H:i:s'));            if($VarId=='' || $VarId==0) {                $ArrUpdateData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrResult = $this->membellmodel->saveEmbellTypeInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manageembelltype() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarEmbellName											= xssclean($this->input->post('en'));        $VarStatus  											= xssclean($this->input->post('s'));        $VarAfilter  											= xssclean($this->input->post('afilter'));        $clickedColumnId  											= xssclean($this->input->post('columnId'));        $newsortorder  											= xssclean($this->input->post('sortorder'));        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'membelltype/manageembelltype/';            $config['total_rows']								= $this->membellmodel->fnCountEmbellType($VarEmbellName,$VarStatus,$VarAfilter);            $config['per_page'] = $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "e.dateupdated";            $sortorder											= "desc";            $ArrDbCols = array('e.embellname','e.status','e.updatedby','e.dateupdated');            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrEmbellTypeList								    = $this->membellmodel->fnListEmbellType($VarEmbellName,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAfilter)->result();            $data['pagination']									= $this->pagination->create_linkswithajax('EmbellType');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrEmbellTypeList as $ObjEmbell){                $ArrFnlList[$i]['id']						    = $ObjEmbell->id;                $ArrFnlList[$i]['n']						    = $ObjEmbell->embellname;                $ArrFnlList[$i]['m']						    = $ObjEmbell->medium;                $ArrFnlList[$i]['ub']						    = $ObjEmbell->contactname;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjEmbell->status];                $ArrFnlList[$i]['du']						    = date('d-m-Y H:i:s',strtotime($ObjEmbell->dateupdated));                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'manageembelltype');        }    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->membellmodel->fnChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }    function delEmbellTypeInfo() {        $VarEmbellId                                            = xssclean($this->input->post('id'));        $VarUpdatedBy                                           = fnGetUserLoggedInfo();        if($VarEmbellId>=1) {            $ArrResult             					            = $this->membellmodel->fnDelEmbellType($VarEmbellId,$VarUpdatedBy);        } else {            $ArrResult['errcode']						        = -1;            $ArrResult['msg']							        = '';        }        echo json_encode($ArrResult);    }    function fnChangeStatusRes () {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->membellmodel->fnChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }}